//! The About window: what this is, who made it, and what it's built from.

use eframe::egui::{self, RichText};

pub const VERSION: &str = env!("CARGO_PKG_VERSION");
const DESCRIPTION: &str =
    "A lightweight audio editor for recording, editing and batch exporting voicelines, one file per clip.";
const PRODUCER: &str = "Kingdom Pots";
const DEVELOPED_WITH: &str = "Claude Opus 5.5";

/// Generated by `scripts/generate_notices.py`.
pub const NOTICES: &str = include_str!("../THIRD_PARTY_NOTICES.txt");

/// Name, licence and what it does here.
const COMPONENTS: [(&str, &str, &str); 11] = [
    ("egui / eframe", "MIT or Apache-2.0", "interface and window"),
    ("cpal", "Apache-2.0", "microphone, system audio and playback"),
    ("Symphonia", "MPL-2.0", "reading audio files"),
    ("Rubato", "MIT or Apache-2.0", "sample rate conversion"),
    ("audioadapter-buffers", "MIT or Apache-2.0", "passing audio to the sample rate converter"),
    ("tempfile", "MIT or Apache-2.0", "safe export file creation"),
    ("Hound", "Apache-2.0", "writing WAV files"),
    ("LAME via mp3lame-encoder", "LGPL-3.0", "writing MP3 files"),
    ("vorbis_rs, aoTuV/Lancer Vorbis, Ogg", "BSD-3-Clause", "writing OGG files"),
    ("rfd", "MIT", "file and folder dialogs"),
    ("Phosphor Icons via egui-pop-phosphor", "MIT or Apache-2.0", "interface icons"),
];

#[derive(Default)]
pub struct AboutWindow {
    page: Option<Page>,
    logo: Option<egui::TextureHandle>,
}

#[derive(Clone, Copy, PartialEq)]
enum Page {
    About,
    Notices,
}

impl AboutWindow {
    pub fn open(&mut self) {
        self.page = Some(Page::About);
    }

    pub fn is_open(&self) -> bool {
        self.page.is_some()
    }

    pub fn show(&mut self, ctx: &egui::Context) {
        let Some(page) = self.page else { return };
        let logo = self.logo.get_or_insert_with(|| load_logo(ctx)).id();
        let max_height = (ctx.content_rect().height() - 110.0).max(100.0);

        let mut next = Some(page);
        let response = egui::Modal::new(egui::Id::unique("about_window")).show(ctx, |ui| {
            ui.set_width(560.0_f32.min(ctx.content_rect().width() - 60.0));
            match page {
                Page::About => about_page(ui, logo, max_height),
                Page::Notices => notices_page(ui, max_height),
            }
            ui.separator();
            ui.horizontal(|ui| match page {
                Page::About => {
                    if ui.button("View notices").on_hover_text("Read the full licence texts").clicked() {
                        next = Some(Page::Notices);
                    }
                    if ui.button("Close").on_hover_text("Close this window (Esc)").clicked() {
                        next = None;
                    }
                }
                Page::Notices => {
                    if ui.button("Back").on_hover_text("Return to About (Esc)").clicked() {
                        next = Some(Page::About);
                    }
                }
            });
        });
        if response.should_close() {
            next = match page {
                Page::Notices => Some(Page::About),
                Page::About => None,
            };
        }
        self.page = next;
    }
}

fn load_logo(ctx: &egui::Context) -> egui::TextureHandle {
    let icon = eframe::icon_data::from_png_bytes(include_bytes!("../assets/logo/exports/kantan_64.png"))
        .expect("the embedded logo is a valid PNG");
    let image = egui::ColorImage::from_rgba_unmultiplied([icon.width as usize, icon.height as usize], &icon.rgba);
    ctx.load_texture("about_logo", image, egui::TextureOptions::LINEAR)
}

fn about_page(ui: &mut egui::Ui, logo: egui::TextureId, max_height: f32) {
    ui.horizontal(|ui| {
        ui.image((logo, egui::vec2(64.0, 64.0)));
        ui.vertical(|ui| {
            ui.heading("Kantan Audio Manager");
            ui.label(format!("Version {VERSION}"));
        });
    });
    ui.add_space(4.0);
    egui::ScrollArea::vertical().max_height(max_height - 80.0).show(ui, |ui| {
        ui.label(DESCRIPTION);
        ui.add_space(6.0);
        ui.label(format!("Produced by {PRODUCER}"));
        ui.label(format!("Developed with {DEVELOPED_WITH}"));
        ui.label(format!("Open source under the MIT License. Copyright (c) 2026 {PRODUCER}"));
        ui.add_space(6.0);
        ui.label(RichText::new("Open-source components").strong());
        for (name, licence, role) in COMPONENTS {
            ui.label(format!("{name} ({licence}): {role}"));
        }
    });
}

/// Draws only the visible lines, because the full text is very long.
fn notices_page(ui: &mut egui::Ui, max_height: f32) {
    ui.heading("Third-party notices");
    let lines: Vec<&str> = NOTICES.lines().collect();
    let row_height = ui.text_style_height(&egui::TextStyle::Monospace);
    egui::ScrollArea::both()
        .max_height(max_height - 30.0)
        .auto_shrink([false, false])
        .show_rows(ui, row_height, lines.len(), |ui, rows| {
            for line in &lines[rows] {
                // Wrapping would break the fixed row height that scrolling relies on.
                ui.add(egui::Label::new(RichText::new(*line).monospace()).extend());
            }
        });
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_version_comes_from_the_build() {
        assert_eq!(VERSION, "0.5.0");
    }

    #[test]
    fn notices_cover_every_listed_component_with_full_licence_texts() {
        for name in [
            "eframe", "egui", "cpal", "symphonia", "rubato", "audioadapter-buffers", "hound",
            "mp3lame-sys", "mp3lame-encoder", "vorbis_rs", "aotuv_lancer_vorbis_sys", "ogg_next_sys",
            "rfd", "egui-pop-phosphor",
        ] {
            let heading = format!("\n{name} ");
            assert!(NOTICES.contains(&heading), "{name} is missing from the notices");
        }
        assert!(NOTICES.contains("GNU LESSER GENERAL PUBLIC LICENSE"));
        assert!(NOTICES.contains("Mozilla Public License"));
    }
}
